"""audit-ai-service — observability module (generated by A2C CodeGenAgent).

Structured JSON logging with a request-scoped correlation id, in-process
metrics (counters and latency samples) and a p95 SLO check. Platform
exporters (CloudWatch, Cloud Monitoring, Azure Monitor, OpenTelemetry)
read from `metrics`; this module has no cloud dependency.
"""
import json
import logging
import time
import uuid
from contextlib import contextmanager
from contextvars import ContextVar
from typing import Dict, Iterator, List

correlation_id: ContextVar[str] = ContextVar("correlation_id", default="")
logger = logging.getLogger("audit-ai-service")


class JsonFormatter(logging.Formatter):
    """One JSON object per log line, always carrying the correlation id."""

    def format(self, record: logging.LogRecord) -> str:
        payload = {
            "ts": round(record.created, 3),
            "level": record.levelname,
            "logger": record.name,
            "message": record.getMessage(),
            "correlation_id": correlation_id.get(),
        }
        payload.update(getattr(record, "fields", {}))
        return json.dumps(payload, default=str)


def configure_logging(level: str = "INFO") -> None:
    handler = logging.StreamHandler()
    handler.setFormatter(JsonFormatter())
    root = logging.getLogger()
    root.handlers[:] = [handler]
    root.setLevel(level)


class Metrics:
    """In-process counters and latency samples."""

    def __init__(self) -> None:
        self.counters: Dict[str, int] = {}
        self.latencies_ms: Dict[str, List[float]] = {}

    def increment(self, name: str, value: int = 1) -> None:
        self.counters[name] = self.counters.get(name, 0) + value

    def observe(self, name: str, millis: float) -> None:
        self.latencies_ms.setdefault(name, []).append(millis)

    def p95(self, name: str) -> float:
        samples = sorted(self.latencies_ms.get(name, []))
        if not samples:
            return 0.0
        return samples[min(len(samples) - 1, int(round(0.95 * (len(samples) - 1))))]


metrics = Metrics()


@contextmanager
def traced(operation: str) -> Iterator[str]:
    """Time an operation, count success/error and log both outcomes."""
    if not correlation_id.get():
        correlation_id.set(str(uuid.uuid4()))
    start = time.perf_counter()
    try:
        yield correlation_id.get()
        metrics.increment(f"{operation}.success")
    except Exception:
        metrics.increment(f"{operation}.error")
        logger.exception("operation failed", extra={"fields": {"operation": operation}})
        raise
    finally:
        elapsed = (time.perf_counter() - start) * 1000
        metrics.observe(operation, elapsed)
        logger.info("operation finished",
                    extra={"fields": {"operation": operation, "latency_ms": round(elapsed, 2)}})


class SLOChecker:
    """p95 latency objective for one operation."""

    def __init__(self, operation: str, p95_target_ms: float) -> None:
        self.operation, self.p95_target_ms = operation, p95_target_ms

    def met(self) -> bool:
        return metrics.p95(self.operation) <= self.p95_target_ms
